const mensagens = items.map((i) => i.json);

const grupos = {};
for (const m of mensagens) {
  const chave = `${m.instancia}||${m.contato}`;
  if (!grupos[chave]) {
    grupos[chave] = {
      instancia: m.instancia,
      contato: m.contato,
      contato_nome: m.contato_nome,
      mensagens: [],
    };
  }
  grupos[chave].mensagens.push(m);
}

return Object.values(grupos)
  .filter((g) => g.mensagens.length > 0)
  .map((g) => ({
    json: {
      instancia: g.instancia,
      contato: g.contato,
      contato_nome: g.contato_nome,
      periodo_inicio: g.mensagens[0].timestamp,
      periodo_fim: g.mensagens[g.mensagens.length - 1].timestamp,
      transcricao: g.mensagens
        .map((m) => `[${m.timestamp}] ${m.direcao === 'enviada' ? 'Colaborador' : 'Cliente'}: ${m.conteudo}`)
        .join('\n'),
    },
  }));

const item = $input.item.json;

const systemPrompt = `Você é um auditor de qualidade de atendimento via WhatsApp. Responda SOMENTE com um JSON válido, sem markdown, exatamente no formato: {"resumo": string, "alerta": boolean, "tipo_alerta": string|null, "trecho_relevante": string|null}.\n\nMarque alerta=true quando detectar qualquer um destes casos na conversa:\n- cliente insatisfeito\n- pergunta do cliente sem resposta do colaborador\n- promessa feita fora do script/autorização (descontos, prazos, condições não padrão)\n- demora excessiva de resposta do colaborador\n- linguagem inadequada ou rude\n\ntipo_alerta deve ser um dos valores: "cliente_insatisfeito", "pergunta_sem_resposta", "promessa_fora_script", "demora_resposta", "linguagem_inadequada". Use null quando alerta=false.\ntrecho_relevante deve citar o trecho da conversa que motivou o alerta, ou null se não houver alerta.`;

const userPrompt = `Conversa entre o colaborador da instância "${item.instancia}" e o contato "${item.contato_nome || item.contato}" (período de ${item.periodo_inicio} a ${item.periodo_fim}):\n\n${item.transcricao}`;

return [
  {
    json: {
      instancia: item.instancia,
      contato: item.contato,
      periodo_inicio: item.periodo_inicio,
      periodo_fim: item.periodo_fim,
      claudeRequest: {
        model: 'claude-sonnet-5',
        max_tokens: 1024,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }],
      },
    },
  },
];

const resposta = $input.item.json;
const original = $('Montar Prompt Claude').item.json;

let texto = '';
try {
  texto = (resposta.content && resposta.content[0] && resposta.content[0].text) || '';
} catch (e) {
  texto = '';
}

texto = texto.replace(/```json/g, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(texto);
} catch (e) {
  parsed = { resumo: 'Falha ao interpretar resposta da IA.', alerta: false, tipo_alerta: null, trecho_relevante: null };
}

const tiposValidos = [
  'cliente_insatisfeito',
  'pergunta_sem_resposta',
  'promessa_fora_script',
  'demora_resposta',
  'linguagem_inadequada',
];

const tipoAlerta = parsed.alerta && tiposValidos.includes(parsed.tipo_alerta) ? parsed.tipo_alerta : (parsed.alerta ? 'cliente_insatisfeito' : null);

return [
  {
    json: {
      instancia: original.instancia,
      contato: original.contato,
      resumo: parsed.resumo || '',
      tipo_alerta: tipoAlerta,
      trecho_relevante: parsed.trecho_relevante || null,
      periodo_inicio: original.periodo_inicio,
      periodo_fim: original.periodo_fim,
    },
  },
];
